CREATE TABLE IF NOT EXISTS account_token_usage (account_id VARCHAR(36), hour_number BIGINT, provider VARCHAR(32), model VARCHAR(128), requests BIGINT DEFAULT 0 NOT NULL, unmetered_requests BIGINT DEFAULT 0 NOT NULL, input_tokens BIGINT DEFAULT 0 NOT NULL, cache_creation_tokens BIGINT DEFAULT 0 NOT NULL, cache_read_tokens BIGINT DEFAULT 0 NOT NULL, output_tokens BIGINT DEFAULT 0 NOT NULL, CONSTRAINT pk_account_token_usage PRIMARY KEY (account_id, hour_number, provider, model), CONSTRAINT fk_account_token_usage_account_id__id FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE CASCADE ON UPDATE RESTRICT);
